diff --git a/src/cache.ts b/src/cache.ts
index 9fa8c53..9208bb5 100644
--- a/src/cache.ts
+++ b/src/cache.ts
@@ -1,20 +1,44 @@
+import * as fs from "fs";
+import * as path from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const SESSIONS_DIR = path.join(process.cwd(), ".sessions");
+
+const ensureDir = (): void => {
+  if (!fs.existsSync(SESSIONS_DIR)) {
+    fs.mkdirSync(SESSIONS_DIR, { recursive: true });
+  }
+};
+
+const getPath = (key: string): string => {
+  return path.join(SESSIONS_DIR, `${key}.json`);
+};

 export const put = (key: string, value: string, ttlMs: number): void => {
-  store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  ensureDir();
+  const entry: Entry = { value, expiresAt: Date.now() + ttlMs };
+  fs.writeFileSync(getPath(key), JSON.stringify(entry), "utf-8");
 };

 export const get = (key: string): string | null => {
-  const entry = store.get(key);
-  if (entry === undefined) return null;
-  if (entry.expiresAt < Date.now()) {
-    store.delete(key);
+  ensureDir();
+  const filePath = getPath(key);
+
+  if (!fs.existsSync(filePath)) return null;
+
+  try {
+    const data = JSON.parse(fs.readFileSync(filePath, "utf-8")) as Entry;
+    if (data.expiresAt < Date.now()) {
+      fs.unlinkSync(filePath);
+      return null;
+    }
+    return data.value;
+  } catch {
+    fs.unlinkSync(filePath);
     return null;
   }
-  return entry.value;
 };
